:root {
  --ink: #25323a;
  --paper: #fffdf6;
  --rail-red: #d95d46;
  --line: #d8d0c1;
}

.pass {
  box-sizing: border-box;
  width: 470px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
  padding: 14px;
}

.pass__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.pass__eyebrow {
  margin: 0 0 3px;
  color: var(--rail-red);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.pass__title {
  margin: 0;
  color: var(--ink);
  font-size: 23px;
  line-height: 1.1;
}

.pass__badge {
  background: var(--rail-red);
  border-radius: 999px;
  color: var(--paper);
  padding: 6px 9px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.pass__body {
  border-top: 1px dashed var(--line);
  margin-top: 12px;
  padding-top: 10px;
}

.pass__note {
  margin: 0;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.45;
}

.pass__footer {
  margin-top: 12px;
}

.pass__button {
  width: 100%;
  background: var(--ink);
  border: 0;
  border-radius: 7px;
  color: var(--paper);
  padding: 9px 12px;
  font-size: 13px;
  font-weight: 700;
}
